<div class="headline"><div><h1>Eventos</h1><p class="subtitle">Crea, modifica y consulta tus actividades deportivas.</p></div><a class="btn" href="<?= h(url('evento_form')) ?>">+ Nuevo evento</a></div>
            <section class="panel"><form class="search" method="get"><input type="hidden" name="page" value="eventos"><input type="search" name="q" placeholder="Buscar por nombre o ubicación" value="<?= h($q) ?>"><button class="btn btn-light">Buscar</button></form></section>
            <section class="panel"><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Fecha</th><th>Ubicación</th><th>Inscritos</th><th>Acciones</th></tr></thead><tbody>
            <?php foreach ($rows as $r): ?><tr><td><strong><?= h($r['nombre']) ?></strong><?php if ($r['descripcion']): ?><div class="muted"><?= h(mb_strimwidth($r['descripcion'], 0, 100, '…', 'UTF-8')) ?></div><?php endif; ?></td><td><?= h($r['fecha']) ?></td><td><?= h($r['ubicacion']) ?></td><td><span class="pill"><?= (int)$r['inscritos'] ?></span></td><td><div class="buttons"><a class="btn btn-light btn-sm" href="<?= h(url('evento_form', ['id'=>$r['evento_id']])) ?>">Editar</a><form method="post" data-confirm="¿Eliminar este evento?" ><input type="hidden" name="action" value="delete_evento"><input type="hidden" name="id" value="<?= (int)$r['evento_id'] ?>"><?= csrf_field() ?><button class="btn btn-danger btn-sm">Eliminar</button></form></div></td></tr><?php endforeach; ?>
            <?php if (!$rows): ?><tr><td class="empty" colspan="5">No se encontraron eventos.</td></tr><?php endif; ?></tbody></table></div></section>
